def _can_reach_itself(graph, current, target, visited):
    """Check if current node can reach target node."""
    if current == target:
        return True
    if current in visited or current not in graph:
        return False
    visited = visited | {current}
    return any(_can_reach_itself(graph, neighbor, target, visited) 
               for neighbor in graph[current])
